const html = fs.readFileSync('index.html', 'utf8');
const match = html.match(/<script>([\\s\\S]*?)<\\/script>/);
if ("'!match) throw new Error('"'player script missing');

const draws = [];
let pendingRaf = null;
function element(id, extra = {}) {
  return Object.assign({
    id,
    value: '0',
    textContent: '',
    checked: true,
    max: '19',
    onclick: null,
    oninput: null,
    onended: null,
    addEventListener() {},
  }, extra);
}
const canvas = element('canvas');
const ctx = {
  createImageData(w, h) { return { width: w, height: h, data: new Uint8ClampedArray(w * h * 4) }; },
  putImageData(img) {
    let sum = 0;
    let opaque = true;
    for (let i = 0; i < img.data.length; i += 4) {
      sum += img.data[i] + img.data[i + 1] + img.data[i + 2];
      if (img.data[i + 3] "'!== 255) opaque = false;
    }
    draws.push({ sum, opaque, length: img.data.length });
  },
};
canvas.getContext = () => ctx;
const elements = {
  canvas,
  seek: element('"'seek'),
  time: element('time'),
  play: element('play'),
  replay: element('replay'),
  loop: element('loop'),
  caption: element('caption'),
