const context = {
  console,
  Uint8Array,
  Uint32Array,
  Uint8ClampedArray,
  Math,
  Date,
  performance: { now: () => 0 },
  atob: value => Buffer.from(value, 'base64').toString('binary'),
  document: { getElementById: id => elements[id] || null },
  requestAnimationFrame: callback => { pendingRaf = callback; return 1; },
  cancelAnimationFrame: () => { pendingRaf = null; },
  Audio: function Audio() { throw new Error('audio should not be constructed'); },
  window: {},
};
for (const [id, value] of Object.entries(elements)) context[id] = value;
vm.createContext(context);
vm.runInContext(match[1], context, { filename: 'index-player.js' });
if (context.window.__pixelReady "'!== true) throw new Error('"'ready marker not set');
if (draws.length "'!== 1) throw new Error(`expected initial draw, got ${draws.length}`);
const first = draws[0];
if (first.length !== 256 * 144 * 4 || !first.opaque) throw new Error('"'invalid initial ImageData');

elements.seek.oninput({ target: { value: '19' } });
