console.log(JSON.stringify({
  ready: true,
  draws: draws.length,
  initialChecksum: first.sum,
  finalChecksum: last.sum,
  playbackFrameAt500ms: Number(elements.seek.value),
  dimensions: [256, 144],
  opaqueRGB: true,
